/** Par de bancos y moneda: índice de los arreglos [0:12,0:12,0:05] del ALGOL. */
public record ParCruce(int bancoOrigen, int bancoDestino, int moneda) {
    public ParCruce {
        if (bancoOrigen < 0 || bancoOrigen > 12 || bancoDestino < 0 || bancoDestino > 12
                || moneda < 0 || moneda > 5) {
            throw new IllegalArgumentException("Fuera de rango [0:12,0:12,0:05]: " + this);
        }
    }
}

/** Totales de un par. DOUBLE del ALGOL -> BigDecimal escala 2 (pesos con centavos). */
public final class TotalesCruce {
    BigDecimal cargos = BigDecimal.ZERO.setScale(2);       // TOTCAR_BNX / TOTCAR_BNC
    BigDecimal abonos = BigDecimal.ZERO.setScale(2);       // TOTABO_BNX / TOTABO_BNC
    BigDecimal iniCargos = BigDecimal.ZERO.setScale(2);    // INICAR_*
    BigDecimal iniAbonos = BigDecimal.ZERO.setScale(2);    // INIABO_*
    long numCargos, numAbonos;                             // INUMCAR_* / INUMABO_*
}

/** Estado residente de la librería. Antes: variables globales compartidas por todos los run-units. */
@Component
public class EstadoCruce {
    final Map<ParCruce, TotalesCruce> banamex     = new ConcurrentHashMap<>();  // *_BNX
    final Map<ParCruce, TotalesCruce> contraparte = new ConcurrentHashMap<>();  // *_BNC / *_OTRO
    final Map<ParCruce, BigDecimal> liq1078 = new ConcurrentHashMap<>();        // LIQ_1078
    final Map<ParCruce, BigDecimal> liq2129 = new ConcurrentHashMap<>();        // LIQ_2129
    final Map<ParCruce, AtomicLong> numLiq1078 = new ConcurrentHashMap<>();
    final Map<ParCruce, AtomicLong> numLiq2129 = new ConcurrentHashMap<>();
    final Set<ParCruce> inicializados = ConcurrentHashMap.newKeySet();          // INICIO_MONEDA = 1
    volatile int fechaProceso;     // FECPROC
    volatile long autorizacion;    // AUT: posición del último registro leído en LOG1
}

/**
 * L006 como servicio Spring. Conserva la misma interfaz de tres entry points exportados.
 * FREEZE(CONTROL, PROC_CONTROL): la librería queda residente mientras tenga usuarios;
 * en el destino ese ciclo lo da el contenedor (singleton + SmartLifecycle).
 */
@Service
@RequiredArgsConstructor
public class CruceInterbancarioService implements SmartLifecycle {

    private final InicializadorCruce levanta;     // LEVANTA: versiones, CSI, catálogo, base, log
    private final SaldosCruce saldos;              // SALDOS(DATOSE)
    private final MovimientosCruce movimientos;    // MOVIMIENTOS(DATOSM)
    private final BaseCruce base;                  // BASE(DATOSB)
    private final Semaforos semaforos;             // EVENT CON_SDO, CON_MOV, ANALIZA
    private volatile boolean activo;

    @Override
    public void start() {
        levanta.ejecuta();
        semaforos.liberaConsultaSaldos();          // CAUSE(CON_SDO)
        semaforos.liberaConsultaMovimientos();     // CAUSE(CON_MOV)
        semaforos.liberaAnalisis();                // CAUSE(ANALIZA)
        activo = true;
    }

    public RespuestaSaldos saldos(SolicitudSaldos s)            { return saldos.atiende(s); }
    public RespuestaMovimientos movimientos(SolicitudMovs s)    { return movimientos.atiende(s); }
    public int base(OperacionBase op)                           { return base.atiende(op); }

    @Override public void stop()        { activo = false; }   // GOINGAWAY
    @Override public boolean isRunning() { return activo; }
}

/** SUMA_ARCHIVO: recorre LOG1 desde AUT+1 hasta la función 99. */
@Component
@RequiredArgsConstructor
class SumaArchivoLog {

    private final LectorLog1 log1;            // registros de 75 bytes, acceso por posición
    private final AcumuladorCruce acumulador;
    private final EstadoCruce estado;
    private final L006Properties props;       // l006.banco-banamex: 2

    void ejecuta() {
        long aut = estado.autorizacion;
        RegistroLog r = log1.lee(++aut);
        while (r.funcion() != 99) {
            boolean altaActiva = r.funcion() == 1 && r.status() == 1;
            boolean origenValido = r.origen() == 1 || r.origen() == 2;
            boolean noAmbosBanamex = r.bancoDestino() != props.bancoBanamex()
                                  || r.bancoOrigen()  != props.bancoBanamex();
            if (altaActiva && origenValido && noAmbosBanamex) {
                acumulador.acumula(r, Signo.SUMA);         // SUMA_RESTA := 0
            }
            r = log1.lee(++aut);
        }
        estado.autorizacion = aut - 1;                     // AUT := * - 1
    }
}

@Component
@RequiredArgsConstructor
class AcumuladorCruce {

    private static final int LIQ_OTR_A_BNX = 1078;   // l006.claves.liquidacion-otr
    private static final int LIQ_BNX_A_OTR = 2129;   // l006.claves.liquidacion-bnx
    private final EstadoCruce estado;
    private final CatalogoClaves catalogo;           // ACLAVES: naturaleza por clave (S080)
    private final MovimientosCruceRepository movs;
    private final L006Properties props;

    /** ACUMULA_REG. Solo operaciones cruzadas: banco origen distinto de banco destino. */
    void acumula(RegistroLog r, Signo signo) {
        if (r.bancoOrigen() == r.bancoDestino()) return;
        ParCruce par = new ParCruce(r.bancoOrigen(), r.bancoDestino(), r.moneda());
        for (Ocurrencia o : r.ocurrencias()) {                 // hasta 5; corta en la primera clave 0
            if (o.clave() <= 0) break;
            BigDecimal importe = o.importeCentavos().movePointLeft(2).multiply(signo.factor());
            switch (o.clave()) {
                case LIQ_OTR_A_BNX -> movs.registra(r, o.clave(),
                        estado.liq1078.merge(par, importe, BigDecimal::add), estado.numLiq1078, par);
                case LIQ_BNX_A_OTR -> movs.registra(r, o.clave(),
                        estado.liq2129.merge(par, importe, BigDecimal::add), estado.numLiq2129, par);
                default -> {
                    var mapa = (r.bancoOrigen() == props.bancoBanamex()) ? estado.banamex : estado.contraparte;
                    TotalesCruce t = mapa.computeIfAbsent(par, k -> new TotalesCruce());
                    switch (catalogo.naturaleza(o.clave())) {
                        case 1 -> { t.cargos = t.cargos.add(importe); t.numCargos++; }
                        case 2 -> { t.abonos = t.abonos.add(importe); t.numAbonos++; }
                        default -> log.warn("Clave {} sin naturaleza 1/2: se descarta", o.clave());
                    }
                }
            }
        }
    }
}

@Entity
@Table(name = "s151b15_mov_ope_cruz")
public class MovimientoCruce {
    @EmbeddedId MovimientoCruceId id;   // CSI, FCHCON, SISTEMA, MONEDA, BCOORI, BCODES, HHMMSS, FCHMAQ
    int claveTransaccion;               // B15-MOV-CVETRA
    @Column(precision = 18, scale = 2)
    BigDecimal importe;                 // B15-MOV-IMPMOV
}

@Repository
interface MovimientoCruceJpa extends JpaRepository<MovimientoCruce, MovimientoCruceId> {
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<MovimientoCruce> findWithLockById(MovimientoCruceId id);   // LOCK B15SXCONMOV AT ...
}

@Component
@RequiredArgsConstructor
class MovimientosCruceRepository {
    private final MovimientoCruceJpa jpa;
    private final EstadoCruce estado;

    /** GRABAMOVTO: LOCK por llave; si no existe, CREATE; PUT de campos y STORE. */
    @Transactional
    void registra(RegistroLog r, int clave, BigDecimal acumuladoLiquidacion,
                  Map<ParCruce, AtomicLong> contador, ParCruce par) {
        contador.computeIfAbsent(par, k -> new AtomicLong()).incrementAndGet();
        var id = MovimientoCruceId.de(estado, r);
        MovimientoCruce m = jpa.findWithLockById(id).orElseGet(() -> MovimientoCruce.nuevo(id));
        m.claveTransaccion = clave;
        m.importe = acumuladoLiquidacion;   // el ALGOL graba IMPMOV := LIQ_xxxx[...] (acumulado, no el movimiento)
        jpa.save(m);                        // BEGINTRANSACTION ... STORE ... ENDTRANSACTION AUDIT
    }
}

@Component
@RequiredArgsConstructor
class SaldosCruce {

    private final Semaforos semaforos;
    private final BaseCruce base;
    private final OperacionesSaldo op;    // INICIA, CONSDO, ACTSDO, BORRASALDOS, BORRAMOVTOS

    /** SALDOS(DATOSE). Códigos de retorno conservados: 1, 5, 7, 9, 10. */
    RespuestaSaldos atiende(SolicitudSaldos s) {
        semaforos.tomaConsultaSaldos();               // RESET(CON_SDO)
        try {
            semaforos.esperaAnalisis();               // WAIT(ANALIZA)
            if (!base.abierta()) return RespuestaSaldos.error(5);       // base no disponible
            if (s.bancoOrigen() >= 13 || s.bancoDestino() >= 13 || s.moneda() >= 6)
                return RespuestaSaldos.error(7);                         // bancos o moneda inválidos
            return switch (s.funcion()) {
                case 0 -> op.inicializa(s);           // 9 si el par ya estaba inicializado
                case 1 -> op.consulta(s);
                case 2 -> op.yaInicializado(s) ? op.actualiza(s) : RespuestaSaldos.error(10);
                case 6 -> op.borraSaldosYMovimientos(s);
                case 7 -> op.grabaTodosYCierra(s);    // WAIT(SUMA) + triple ciclo + CLOSE
                default -> RespuestaSaldos.error(1);
            };
        } finally {
            semaforos.liberaConsultaSaldos();         // CAUSE(CON_SDO)
        }
    }
}

/** ACTSDO: diferencias cruzadas del par y grabado en S151B14CONOPECRUZ. */
int actualiza(ParCruce bnx) {
    ParCruce otr = new ParCruce(bnx.bancoDestino(), bnx.bancoOrigen(), bnx.moneda());   // índices invertidos

    BigDecimal carBnx  = total(estado.banamex, bnx).cargos;
    BigDecimal aboBnx  = total(estado.banamex, bnx).abonos;
    BigDecimal carOtro = total(estado.contraparte, otr).cargos;
    BigDecimal aboOtro = total(estado.contraparte, otr).abonos;
    BigDecimal liq1078 = estado.liq1078.getOrDefault(otr, BigDecimal.ZERO);
    BigDecimal liq2129 = estado.liq2129.getOrDefault(bnx, BigDecimal.ZERO);

    // Lo que la contraparte cargó debe verse como abono en Banamex más su liquidación, y viceversa.
    BigDecimal difBnx  = carOtro.subtract(aboBnx).subtract(liq2129);
    BigDecimal difOtro = carBnx.subtract(aboOtro).subtract(liq1078);

    saldosRepo.graba(bnx, carBnx, aboBnx, carOtro, aboOtro, liq1078, liq2129, difBnx, difOtro);
    // En DMSII los importes van x100 (centavos enteros); la columna NUMERIC(…,2) lo hace innecesario.
    return 0;   // el ALGOL no asigna ACTSDO en la rama de éxito; ver pendientes
}

/** PROC_CONTROL: el operador enviaba un número en TASKVALUE (AX). Aquí es un endpoint protegido. */
@RestController
@RequestMapping("/admin/l006")
@PreAuthorize("hasRole('OPERADOR_TESORERIA')")
@RequiredArgsConstructor
class L006AdminController {

    private final BaseCruce base;
    private final LectorLog1 log1;
    private final SaldosCruce saldos;
    private final Semaforos semaforos;
    private final EstadoCruce estado;
    private final L006Properties props;    // l006.sistema-totales: 500

    @PostMapping("/comando/{num}")
    ResponseEntity<String> comando(@PathVariable int num) {
        switch (num) {
            case 1   -> base.abreSiCerrada();                       // BASE(00)
            case 2   -> base.cierraSiAbierta();                     // BASE(01)
            case 3   -> log1.cierra();                              // CLOSE(LOG1, LOCK)
            case 6   -> saldos.atiende(SolicitudSaldos.borrado(     // SALDOS(06 FECPROC CSI 0500)
                            estado.fechaProceso, props.csi(), props.sistemaTotales()));
            case 10  -> { return ResponseEntity.ok("L006 FECHA %08d NIVEL %08d"
                            .formatted(estado.fechaProceso, estado.autorizacion)); }
            case 113 -> semaforos.liberaAnalisis();
            case 115 -> semaforos.liberaSuma();
            default  -> { /* 4, 118..133: ver controlador completo */ }
        }
        return ResponseEntity.accepted().build();
    }
}

/** Evento 1 del ciclo: cada 30 s o ante excepción, analiza lo nuevo del log. */
@Scheduled(fixedDelayString = "${l006.ciclo-analisis:PT30S}")
void cicloAnalisis() {
    if (semaforos.analisisLiberado()) {
        semaforos.esperaSuma();                                     // WAIT(SUMA)
        analizador.analizaFuncion();                                // ANALIZA_FUNCION
        log1.cierra();
    }
}
